/* Learning goals select the interaction. Only terminology uses definition matching. */
'use strict';
const WorkshopEngine=TaskWorkshop;
function wt(text){return typeof text==='string'?text:text?.[state.language==='en'?'en':'zh']||text?.zh||'';}
function hasWorkshop(sec=studySection()){return!!sec?.activity&&sec.activity.kind!=='match';}
let workshopSelected=null,workshopEvidence=false;
const workshopIcons={switchboard:'⚙', 'prompt-lab':'☁',portfolio:'⛵',ledger:'◷',canvas:'✧',balance:'⚖',permissions:'⚿',incident:'♜',readiness:'◉','data-pipeline':'⌘',dialogue:'♧',stagegate:'🚂'};
function draftFor(round,p){const d=p.draft;if(!d.initialized){d.initialized=true;d.selected=[];d.placements={};d.values={};d.order=[];d.pool=KnowledgePractice.shuffle((round.items||round.options||[]).map(i=>i.id));if(round.type==='rate')for(const f of round.fields)d.values[f.id]=f.min??0;}return d;}
function workshopCard(item,extra=''){return `<button class="workshop-card" data-workshop-item="${esc(item.id)}" draggable="true" ${extra}><span>${esc(wt(item.text))}</span></button>`;}
function workshopRoundHTML(r,d){
 if(r.type==='sort')return `<div class="workshop-sorting"><div class="workshop-pool">${d.pool.filter(id=>!d.placements[id]).map(id=>workshopCard(r.items.find(i=>i.id===id))).join('')}</div><div class="workshop-bins">${r.bins.map(bin=>`<section><button class="workshop-bin" data-workshop-bin="${bin.id}" data-drop="workshop-bin-${bin.id}"><b>${esc(wt(bin.text))}</b><small>${learningCopy('点击放入已选物件，或拖到这里','Place a selected item here or drag it in')}</small></button><div>${r.items.filter(i=>d.placements[i.id]===bin.id).map(i=>workshopCard(i)).join('')}</div></section>`).join('')}</div></div>`;
 if(r.type==='order')return `<div class="workshop-pool">${d.pool.filter(id=>!d.order.includes(id)).map(id=>workshopCard(r.items.find(i=>i.id===id))).join('')}</div><div class="workshop-track" id="workshopTrack" data-drop="workshop-order"><span>${learningCopy('点击候选物件按顺序铺路，或拖到轨道。箭头可调整次序。','Click candidates in order or drag them onto the track. Use arrows to rearrange.')}</span>${d.order.map((id,i)=>{const item=r.items.find(x=>x.id===id);return `<div class="workshop-track-stop"><b>${i+1}</b><button data-workshop-remove="${id}">${esc(wt(item.text))}</button><button data-workshop-up="${i}" aria-label="${learningCopy('向前移动','Move earlier')}" ${i?'':'disabled'}>↑</button><button data-workshop-down="${i}" aria-label="${learningCopy('向后移动','Move later')}" ${i<d.order.length-1?'':'disabled'}>↓</button></div>`;}).join('')}</div>`;
 if(r.type==='choose')return `<p class="workshop-control-note">${learningCopy('选择所有应采取的行动，再提交决定。','Select every appropriate action, then submit your decision.')}</p><div class="workshop-options ${studySection().activity.kind==='dialogue'?'dialogue-options':''}">${r.options.map(o=>`<button data-workshop-select="${o.id}" aria-pressed="${d.selected.includes(o.id)}" class="${d.selected.includes(o.id)?'chosen':''}"><i>${d.selected.includes(o.id)?'✓':'○'}</i>${esc(wt(o.text))}</button>`).join('')}</div>`;
 if(r.type==='allocate'){const cards=d.selected.map(id=>r.items.find(i=>i.id===id)).filter(Boolean);return `<div class="workshop-budget"><span>${learningCopy('已投入','Committed')} <b>${cards.reduce((a,c)=>a+c.cost,0)} / ${r.budget}</b></span><span>${learningCopy('组合价值','Portfolio value')} <b>${cards.reduce((a,c)=>a+c.value,0)} / ${r.minimumValue}</b></span></div><div class="workshop-investments">${r.items.map(i=>`<button data-workshop-select="${i.id}" class="${d.selected.includes(i.id)?'chosen':''}" aria-pressed="${d.selected.includes(i.id)}"><b>${d.selected.includes(i.id)?'✓':'◇'}</b><span>${esc(wt(i.text))}</span><small>${learningCopy('投入','Cost')} ${i.cost} · ${learningCopy('演练价值','Exercise value')} ${i.value}</small></button>`).join('')}</div>`;}
 if(r.type==='matrix')return `<div class="workshop-matrix-wrap"><table class="workshop-matrix"><thead><tr><th>${learningCopy('角色 / 职责','Role / responsibility')}</th>${r.columns.map(col=>`<th>${esc(wt(col.text))}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr><th>${esc(wt(row.text))}</th>${r.columns.map(col=>{const id=row.id+':'+col.id;return `<td><button data-workshop-select="${id}" aria-label="${esc(wt(row.text)+' · '+wt(col.text))}" aria-pressed="${d.selected.includes(id)}" class="${d.selected.includes(id)?'chosen':''}">${d.selected.includes(id)?'✓':'＋'}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;
 if(['number','edit','rate'].includes(r.type))return `<div class="workshop-fields ${r.type==='rate'?'workshop-radar':''}">${r.fields.map(f=>`<label class="workshop-field"><span>${esc(wt(f.label))}</span><input data-workshop-field="${f.id}" ${r.type==='rate'?`type="range" min="${f.min??0}" max="${f.max??2}" step="1"`:typeof f.expected==='number'?'type="number" step="any"':'type="text" maxlength="100"'} value="${esc(String(d.values[f.id]??''))}" aria-label="${esc(wt(f.label))}">${r.type==='rate'?`<output id="workshopValue_${f.id}">${d.values[f.id]??0}</output>`:''}</label>`).join('')}</div>${r.type==='number'?'<div class="workshop-calculator-art" aria-hidden="true">＋　－　×　÷</div>':''}`;
 return '';
}
function openTaskWorkshop(){const sec=studySection();if(!hasWorkshop()){openKnowledgeMatch();return;}if(!sec.lessons.every(l=>studyState().deposited.includes(l.id))){studyLocked();return;}workshopSelected=null;workshopEvidence=false;renderTaskWorkshop();}
function renderTaskWorkshop(){const sec=studySection(),plan=sec.activity,p=WorkshopEngine.progress(studyState(),sec),round=plan.rounds[p.round];if(!round){modal(`<span class="eyebrow">${learningCopy('小节成果','Section result')}</span><h2 id="dialogTitle">${esc(wt(plan.title))}</h2><div class="workshop-seal">✦</div><p>${learningCopy('你已完成本节各项操作与判断，可以把成果收进知识素材箱。','You completed this section’s actions and decisions. Keep the result in your knowledge chest.')}</p><div class="actions"><button id="workshopBack">${learningCopy('返回场景','Back to scene')}</button><button id="workshopFinish" class="primary">${learningCopy('收好成果，完成小节','Keep the result and complete section')}</button></div>`);$('workshopBack').onclick=close;$('workshopFinish').onclick=()=>{if(!WorkshopEngine.mastered(studyState(),sec)||!CS.seal(studyState(),currentCourse()))return;close();render();save();toast(learningCopy('本节已完成，新的学习素材已刷新。','Section complete. New learning material is ready.'));};return;}
 const draft=draftFor(round,p),related=sec.lessons.filter(l=>round.skills.includes(l.skill));modal(`<div class="task-workshop workshop-${plan.kind}"><div class="workshop-heading"><span class="workshop-emblem">${workshopIcons[plan.kind]||'✦'}</span><div><span class="eyebrow">Task ${sec.id} · ${learningCopy('已读知识的应用','Apply your learning')}</span><h2 id="dialogTitle">${esc(wt(plan.title))}</h2></div></div><p>${esc(wt(plan.brief))}</p><div class="workshop-stages">${plan.rounds.map((r,i)=>`<span class="${i<p.round?'done':i===p.round?'current':''}">${i<p.round?'✓':i+1}</span>`).join('')}<small>${p.round+1}/${plan.rounds.length}</small></div><div class="workshop-case">${plan.kind==='dialogue'?'<span class="workshop-speaker">🦊</span>':''}<p>${esc(wt(round.prompt))}</p></div>${workshopRoundHTML(round,draft)}<p id="workshopFeedback" class="workshop-feedback" role="status"></p><div class="actions"><button id="workshopBack">${learningCopy('稍后继续','Continue later')}</button><button id="workshopRead">${learningCopy('查看相关知识','Review related knowledge')}</button><button id="workshopReset">${learningCopy('重置本轮操作','Reset this round')}</button><button id="workshopSubmit" class="primary">${learningCopy('提交这一轮','Submit this round')}</button></div>${workshopEvidence?`<section class="workshop-evidence"><h3>${learningCopy('本轮涉及的知识','Knowledge for this round')}</h3>${related.map(l=>`<details><summary>${esc(knowledgeText(l,'title'))}</summary><p>${esc(knowledgeText(l,'body'))}</p><p>${esc(knowledgeText(l,'example'))}</p>${l.boundary?`<p class="knowledge-boundary">${esc(knowledgeText(l,'boundary'))}</p>`:''}</details>`).join('')}</section>`:''}</div>`,true);
 $('workshopBack').onclick=()=>{close();save();};$('workshopRead').onclick=()=>{workshopEvidence=!workshopEvidence;renderTaskWorkshop();};$('workshopReset').onclick=()=>{p.draft={};workshopSelected=null;save();renderTaskWorkshop();};$('workshopSubmit').onclick=()=>submitTaskWorkshop();
 document.querySelectorAll('[data-workshop-select]').forEach(el=>el.onclick=()=>{const id=el.dataset.workshopSelect;draft.selected=draft.selected.includes(id)?draft.selected.filter(x=>x!==id):[...draft.selected,id];save();renderTaskWorkshop();});
 document.querySelectorAll('[data-workshop-item]').forEach(el=>{el.onclick=()=>{const id=el.dataset.workshopItem;if(round.type==='order'){if(!draft.order.includes(id))draft.order.push(id);save();renderTaskWorkshop();}else{workshopSelected=id;$('workshopFeedback').textContent=learningCopy('已选中，请点击目标窗口。','Selected. Choose the destination.');document.querySelectorAll('[data-workshop-item]').forEach(n=>n.classList.toggle('selected',n.dataset.workshopItem===id));}};bindDraggable(el,{workshopItem:el.dataset.workshopItem,section:sec.id,round:round.id});});
 document.querySelectorAll('[data-workshop-bin]').forEach(el=>{el.onclick=()=>placeWorkshopItem(workshopSelected,el.dataset.workshopBin);bindDrop(el,'workshop-bin-'+el.dataset.workshopBin);});if($('workshopTrack'))bindDrop($('workshopTrack'),'workshop-order');
 document.querySelectorAll('[data-workshop-remove]').forEach(el=>el.onclick=()=>{draft.order=draft.order.filter(id=>id!==el.dataset.workshopRemove);save();renderTaskWorkshop();});for(const [attr,delta]of [['workshopUp',-1],['workshopDown',1]])document.querySelectorAll('[data-'+attr.replace(/[A-Z]/g,x=>'-'+x.toLowerCase())+']').forEach(el=>el.onclick=()=>{const i=+el.dataset[attr],j=i+delta;if(j>=0&&j<draft.order.length)[draft.order[i],draft.order[j]]=[draft.order[j],draft.order[i]];save();renderTaskWorkshop();});
 document.querySelectorAll('[data-workshop-field]').forEach(el=>{el.oninput=()=>{draft.values[el.dataset.workshopField]=el.value;const out=$('workshopValue_'+el.dataset.workshopField);if(out)out.textContent=el.value;save();};el.onchange=el.oninput;});
}
function placeWorkshopItem(id,target){if(!hasWorkshop())return;const sec=studySection(),p=WorkshopEngine.progress(studyState(),sec),r=sec.activity.rounds[p.round];if(!r?.items.some(i=>i.id===id))return;const d=draftFor(r,p);if(r.type==='sort'&&r.bins.some(b=>b.id===target))d.placements[id]=target;else if(r.type==='order'&&!d.order.includes(id))d.order.push(id);else return;workshopSelected=null;save();renderTaskWorkshop();}
function submitTaskWorkshop(){if(!hasWorkshop())return;const sec=studySection(),p=WorkshopEngine.progress(studyState(),sec),r=sec.activity.rounds[p.round];if(!r)return;const answer=JSON.parse(JSON.stringify(draftFor(r,p)));if(!WorkshopEngine.submit(studyState(),sec,answer)){$('workshopFeedback').textContent=learningCopy('还未满足本轮条件：','The conditions are not yet met: ')+wt(r.reason);save();return;}save();modal(`<span class="eyebrow">${learningCopy('这一轮已验证','Round verified')}</span><h2 id="dialogTitle">${esc(wt(sec.activity.title))}</h2><div class="workshop-seal">✓</div><p>${esc(wt(r.reason))}</p><p>${p.round}/${sec.activity.rounds.length}</p><div class="actions"><button id="workshopPause">${learningCopy('暂时返回场景','Pause and return')}</button><button id="workshopNext" class="primary">${p.round===sec.activity.rounds.length?learningCopy('收好本节成果','Keep this section’s result'):learningCopy('进入下一轮','Continue to next round')}</button></div>`);$('workshopNext').onclick=()=>{workshopEvidence=false;renderTaskWorkshop();};$('workshopPause').onclick=close;}
const workshopBasket=openStudyBasket;
openStudyBasket=function(){workshopBasket();if(!hasWorkshop())return;const sec=studySection(),button=$('sealBasket');button.textContent=learningCopy('启动','Start ')+wt(sec.activity.title);button.onclick=openTaskWorkshop;const instruction=$('knowledgeDeviceInstruction');if(instruction)instruction.textContent=learningCopy('先读懂并收齐本节知识，再通过这件装置解决实际情境。','Read and collect this section’s knowledge, then use this device to solve the scenario.');};
const workshopDrag=applyDrag;
applyDrag=function(data,kind,category){if(data?.workshopItem){if(!hasWorkshop())return;const sec=studySection(),p=WorkshopEngine.progress(studyState(),sec);if(data.section!==sec.id||data.round!==sec.activity.rounds[p.round]?.id)return;if(kind.startsWith('workshop-bin-'))placeWorkshopItem(data.workshopItem,kind.slice(13));else if(kind==='workshop-order')placeWorkshopItem(data.workshopItem);return;}workshopDrag(data,kind,category);};
const workshopSeal=CS.seal;
CS.seal=function(s,course){const sec=course.chapters[s.chapter].sections[s.section];if(hasWorkshop(sec)&&!s.sealed.includes(sec.id)&&!WorkshopEngine.mastered(s,sec))return false;return workshopSeal(s,course);};
const workshopRestore=L.restore;
L.restore=function(raw){try{const value=typeof raw==='string'?JSON.parse(raw):JSON.parse(JSON.stringify(raw));for(const[bid,s]of Object.entries(value.chapterStudies||{})){const bank=value.banks?.find(b=>b.id===bid),course=bank?.syllabus||(bid===EXAM_ID?StrategistCourse:null);if(!course)continue;for(let ci=0;ci<course.chapters.length;ci++){const ch=course.chapters[ci],stale=ch.sections.filter(sec=>s.sealed?.includes(sec.id)&&!sec.lessons.every(l=>s.deposited?.includes(l.id)));if(!stale.length)continue;s.previousResults??=[];s.previousResults.push(...s.assessments.filter(a=>a.chapter===ci));s.previousResults=s.previousResults.slice(-100);s.assessments=s.assessments.filter(a=>a.chapter!==ci);s.submitted=s.submitted.filter(i=>i!==ci);s.sealed=s.sealed.filter(id=>!stale.some(sec=>sec.id===id));const section=ch.sections.findIndex(sec=>!s.sealed.includes(sec.id));if(s.chapter===ci){s.section=section;s.mode='learn';s.round=null;}if(s.chapterViews?.[ci])s.chapterViews[ci]={section,mode:'learn',round:null};}if(!WorkshopEngine.validate(s,course))return null;}return workshopRestore(value);}catch{return null;}};
const workshopReplay=replayStudyChapter;
replayStudyChapter=function(){workshopReplay();const confirm=$('confirmStudyReplay'),base=confirm.onclick;confirm.onclick=()=>{const s=studyState();for(const sec of studyChapter().sections)if(s.workshops)delete s.workshops[sec.id];base();};};
const learningArtifacts={switchboard:[11,'调度齿轮','Dispatch gear'], 'prompt-lab':[23,'配方纸片','Recipe fragment'],portfolio:[22,'航线拼图','Route fragment'],ledger:[9,'账房凭证','Ledger receipt'],canvas:[14,'价值拼贴','Value patch'],balance:[33,'守护徽章','Safeguard badge'],permissions:[5,'权限钥匙','Permission key'],incident:[13,'灯塔记录','Lighthouse log'],readiness:[34,'证据仪表','Evidence gauge'],'data-pipeline':[15,'数据晶片','Data chip'],dialogue:[43,'伙伴名牌','Partner badge'],stagegate:[45,'启程车票','Departure ticket']};
const workshopLoot=renderLoot;
renderLoot=function(){workshopLoot();if(!currentCourse()||studyState().mode!=='learn')return;const reserved=new Set(studySection().lessons.filter(l=>l.interaction==='assemble').flatMap(l=>unitParts(l).map(p=>p.art)));if(hasWorkshop())reserved.add((learningArtifacts[studySection().activity.kind]||[23])[0]);let device=studyTheme().device;if(reserved.has(device))device=[38,36,32,31,39,33,34,43].find(n=>!reserved.has(n))??38;document.querySelectorAll('[data-learning-device-art]').forEach(el=>{el.innerHTML=sprites(device);el.dataset.deviceArt=String(device);});if(!hasWorkshop())return;const artifact=learningArtifacts[studySection().activity.kind]||[23,'知识碎片','Knowledge fragment'];document.querySelectorAll('[data-study-fruit]').forEach(el=>{const l=studySection().lessons.find(l=>l.id===el.dataset.studyFruit);if(!l)return;el.innerHTML=`<span class="learning-artifact" data-artifact-kind="${studySection().activity.kind}">${sprites(artifact[0])}</span><small>${esc(learningCopy(artifact[1],artifact[2])+' · '+knowledgeText(l,'title'))}</small>`;});};
